function [yout] = alg_eq(x,u)
Ad = 2.1428*10^17   ;
Ed = 14897          ;
Ap = 3.816*10^10    ;
Ep = 3557           ;
At = 4.50*10^12     ;
Et = 843            ;
fi = 0.6            ;
DeltaHr = -6.99*10^4;
hA = 1.05*10^6      ;
rhoCp = 1506        ;
rhocCpc = 4043      ;
Mm = 104.14         ;
Qim = 108           ;
Qi = 108            ;
Qmm = 378           ;
Qc =1               ;
V = 3000            ;
Vc = 3312.4         ;
If = 0.5888         ;
Mf = 8.6981         ;
Tf = 330            ;
Tcf = 295           ;


y(1)=(Ad*exp(-Ed/x(3))                     );

y(2)=(Ap*exp(-Ep/x(3))                     );

y(3)=(At*exp(-Et/x(3))                     );

y(4)=((Qmm/Qim)*Qi                         );

y(5)=(1.5*y(4) - Qi                        );

y(6)=(Qi + y(5) + y(4)                     );

y(7)=(( ( ( 2*fi*y(1)*x(1) )/y(3) )^(0.5) ));

yout=y;
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
